<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$id=(int)($_GET['id']??$_POST['id']??0);if($id<1){http_response_code(404);exit('Lead not found.');}$allowedStatus=['new','contacted','proposal','won','lost'];$allowedPriority=['low','normal','high'];if($_SERVER['REQUEST_METHOD']==='POST'){$status=(string)($_POST['status']??'new');$priority=(string)($_POST['priority']??'normal');$notes=trim((string)($_POST['notes']??''));if(in_array($status,$allowedStatus,true)&&in_array($priority,$allowedPriority,true)){$db->prepare('UPDATE leads SET status=?,priority=?,notes=? WHERE id=?')->execute([$status,$priority,$notes?:null,$id]);header('Location: lead.php?id='.$id.'&saved=1');exit;}}$stmt=$db->prepare('SELECT * FROM leads WHERE id=? LIMIT 1');$stmt->execute([$id]);$lead=$stmt->fetch();if(!$lead){http_response_code(404);exit('Lead not found.');}$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$esc($lead['name'])?> | Lead</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:1000px"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 mb-1"><?=$esc($lead['name'])?></h1><p class="text-muted mb-0">Lead #<?=$id?> · <?=$esc($lead['email'])?></p></div><a href="leads.php" class="btn btn-outline-dark">Back to Leads</a></div><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Lead updated successfully.</div><?php endif;?><div class="row g-4"><div class="col-lg-7"><div class="card border-0 shadow-sm p-4 h-100"><h2 class="h5">Enquiry</h2><dl class="row mt-3"><dt class="col-sm-4">Name</dt><dd class="col-sm-8"><?=$esc($lead['name'])?></dd><dt class="col-sm-4">Email</dt><dd class="col-sm-8"><a href="mailto:<?=$esc($lead['email'])?>"><?=$esc($lead['email'])?></a></dd><dt class="col-sm-4">Phone</dt><dd class="col-sm-8"><?=$esc($lead['phone']?:'—')?></dd><dt class="col-sm-4">Company</dt><dd class="col-sm-8"><?=$esc($lead['company']?:'—')?></dd><dt class="col-sm-4">Service</dt><dd class="col-sm-8"><?=$esc($lead['service']?:'—')?></dd><dt class="col-sm-4">Budget</dt><dd class="col-sm-8"><?=$esc($lead['budget']?:'—')?></dd><dt class="col-sm-4">Timeline</dt><dd class="col-sm-8"><?=$esc($lead['timeline']?:'—')?></dd><dt class="col-sm-4">Source</dt><dd class="col-sm-8"><?=$esc($lead['source'])?></dd></dl><hr><h3 class="h6">Project message</h3><p class="text-secondary"><?=nl2br($esc($lead['message']))?></p></div></div><div class="col-lg-5"><div class="card border-0 shadow-sm p-4"><h2 class="h5">Pipeline</h2><form method="post" class="mt-3"><input type="hidden" name="id" value="<?=$id?>"><label class="form-label">Status</label><select name="status" class="form-select mb-3"><?php foreach($allowedStatus as $s):?><option value="<?=$s?>" <?=$lead['status']===$s?'selected':''?>><?=ucfirst($s)?></option><?php endforeach;?></select><label class="form-label">Priority</label><select name="priority" class="form-select mb-3"><?php foreach($allowedPriority as $p):?><option value="<?=$p?>" <?=$lead['priority']===$p?'selected':''?>><?=ucfirst($p)?></option><?php endforeach;?></select><label class="form-label">Internal Notes</label><textarea name="notes" rows="7" class="form-control mb-3"><?=$esc($lead['notes'])?></textarea><button class="btn btn-dark w-100">Save Lead</button></form></div></div></div></main></body></html>